import Link from "next/link";

import { buttonVariants } from "@/components/ui/button";
import { Carrossel } from "@/features/dashboard/components/carrossel";
import { CartaoFilme } from "@/features/dashboard/components/cartao-filme";
import type { Secao } from "@/features/recomendacao/tipos";

type Props = {
  secao: Secao;
  /** URL atual (com a rodada), usada no "Tentar de novo". */
  urlAtual: string;
};

export function SecaoRecomendacoes({ secao, urlAtual }: Props) {
  const idTitulo = `secao-${secao.id}`;

  return (
    <section aria-labelledby={idTitulo} className="flex flex-col gap-3">
      <h2 id={idTitulo} className="text-2xl tracking-tight">
        {secao.titulo}
      </h2>
      {secao.erro ? (
        <div className="border-border/60 text-muted-foreground flex flex-wrap items-center gap-3 rounded-lg border border-dashed px-4 py-6 text-sm">
          <p>Não foi possível carregar agora.</p>
          <Link href={urlAtual} className={buttonVariants({ variant: "outline", size: "sm" })}>
            Tentar de novo
          </Link>
        </div>
      ) : (
        <Carrossel rotulo={secao.titulo}>
          {secao.filmes.map((filme) => (
            <li key={filme.id} className="shrink-0 snap-start">
              <CartaoFilme filme={filme} />
            </li>
          ))}
        </Carrossel>
      )}
    </section>
  );
}
/** Esqueleto das seções enquanto o motor busca as recomendações. */
export function EsqueletoSecoes() {
  return (
    <div aria-busy="true" className="flex flex-col gap-10">
      <span className="sr-only">Carregando recomendações</span>
      {Array.from({ length: 3 }, (_, secao) => (
        <div key={secao} className="flex flex-col gap-3">
          <div className="bg-muted h-7 w-56 animate-pulse rounded" />
          <div className="flex gap-4 overflow-hidden">
            {Array.from({ length: 6 }, (_, cartao) => (
              <div
                key={cartao}
                className="bg-muted aspect-[2/3] w-40 shrink-0 animate-pulse rounded-lg md:w-44"
              />
            ))}
          </div>
        </div>
      ))}
    </div>
  );
}
import Image from "next/image";
import Link from "next/link";

import { tituloComAno } from "@/features/filme/formatar";
import { caminhoMidia, type TipoMidia } from "@/lib/midia";
import { urlImagem } from "@/lib/tmdb/imagens";
import type { FilmeResumo } from "@/lib/tmdb/tipos";

export type FilmeCartao = Pick<FilmeResumo, "id" | "titulo" | "posterPath" | "ano"> & {
  /** Série leva para `/serie/{id}` e diz "Série"; sem tipo, é filme. */
  tipo?: TipoMidia;
  nota?: number;
  /** Só quando o filme veio do motor de recomendação. */
  motivo?: string;
};

export function CartaoFilme({ filme }: { filme: FilmeCartao }) {
  const poster = urlImagem(filme.posterPath, "w342");
  const nome = tituloComAno(filme);
  const tipo = filme.tipo ?? "filme";
  const detalhes = [
    tipo === "serie" && "Série",
    filme.ano,
    filme.nota !== undefined && `★ ${filme.nota.toFixed(1)}`,
  ]
    .filter(Boolean)
    .join(" · ");

  return (
    <Link
      href={caminhoMidia({ tipo, tmdbId: filme.id })}
      aria-label={tipo === "serie" ? `${nome}, série` : nome}
      className="group focus-visible:ring-ring/50 flex w-40 flex-col gap-2 rounded-lg outline-none focus-visible:ring-3 md:w-44"
    >
      <div className="bg-muted relative aspect-[2/3] overflow-hidden rounded-lg">
        {poster ? (
          <Image
            src={poster}
            alt=""
            fill
            sizes="(min-width: 768px) 176px, 160px"
            className="object-cover transition-transform duration-300 group-hover:scale-105"
          />
        ) : (
          <div
            data-testid="sem-poster"
            className="text-muted-foreground flex h-full items-center justify-center p-3 text-center text-sm font-medium"
          >
            {filme.titulo}
          </div>
        )}
      </div>
      <div className="flex flex-col gap-0.5">
        <p className="truncate text-sm font-medium">{filme.titulo}</p>
        <p className="text-muted-foreground text-xs">{detalhes}</p>
        {filme.motivo && (
          <p data-testid="motivo" className="text-muted-foreground line-clamp-2 text-xs">
            {filme.motivo}
          </p>
        )}
      </div>
    </Link>
  );
}
