import type { Duracao, Frequencia } from "@/features/preferencias/opcoes";
import type { Reacao } from "@/features/reacoes/opcoes";
import type { FilmeResumo } from "@/lib/tmdb/tipos";

export type ReacaoMotor = {
  tmdbId: number;
  titulo: string;
  reacao: Reacao;
  /** Gêneros do filme, para o bônus de afinidade. */
  generos: number[];
};

export type EntradaMotor = {
  preferencias: {
    generos: number[];
    /** Gêneros que nunca devem aparecer. Padrão: nenhum. */
    generosEvitados?: number[];
    duracao: Duracao;
    frequencia: Frequencia;
    /** Provedores do TMDB que a pessoa assina. Padrão: nenhum. */
    streamings?: number[];
  };
  usuarioId: string;
  /** "Hoje"; o dia é contado no fuso America/Sao_Paulo. */
  data: Date;
  /** Cada "Gerar outras recomendações" soma 1. Padrão 0. */
  rodada?: number;
  /** Reações do usuário ("Não é pra mim", "Gostei", "Amei"). */
  reacoes?: ReacaoMotor[];
  /** IDs do TMDB que nunca devem aparecer. */
  excluir?: number[];
};

export type Recomendacao = FilmeResumo & { motivo: string; pontuacao: number };

export type Secao = {
  /** "streamings", "para-voce", "parecidos-{tmdbId}" ou "genero-{id}". */
  id: string;
  titulo: string;
  filmes: Recomendacao[];
  /** A consulta desta seção falhou; `filmes` vem vazio. */
  erro?: true;
};

/** Gerador pseudoaleatório: devolve números em [0, 1). */
export type Gerador = () => number;
import { GENEROS } from "@/features/preferencias/generos";
import { VERBO_REACAO } from "@/features/reacoes/opcoes";
import type { ReacaoMotor } from "@/features/recomendacao/tipos";

const MAX_GENEROS_NO_MOTIVO = 3;

function listar(nomes: string[]): string {
  if (nomes.length <= 1) return nomes.join("");
  return `${nomes.slice(0, -1).join(", ")} e ${nomes.at(-1)}`;
}

/** "Porque você curte Drama e Thriller", com no máximo 3 gêneros, na ordem de GENEROS. */
export function motivoPorGeneros(generosDoFilme: number[], favoritos: number[]): string {
  const emComum = GENEROS.filter(
    ({ id }) => generosDoFilme.includes(id) && favoritos.includes(id),
  ).map(({ nome }) => nome);
  if (emComum.length === 0) return "Popular entre quem tem gostos parecidos";
  return `Porque você curte ${listar(emComum.slice(0, MAX_GENEROS_NO_MOTIVO))}`;
}

/** "Parecido com X, que você amou". */
export function motivoParecido(origem: ReacaoMotor): string {
  const verbo = origem.reacao === "nao-gostei" ? null : VERBO_REACAO[origem.reacao];
  return verbo ? `Parecido com ${origem.titulo}, ${verbo.motivo}` : `Parecido com ${origem.titulo}`;
}

/** "Porque você amou X" / "Porque você gostou de X". */
export function tituloParecidos(origem: ReacaoMotor): string {
  const verbo = origem.reacao === "nao-gostei" ? null : VERBO_REACAO[origem.reacao];
  return verbo ? `${verbo.titulo} ${origem.titulo}` : `Parecidos com ${origem.titulo}`;
}
import type { Duracao, Frequencia } from "@/features/preferencias/opcoes";
import type { FiltrosDescoberta } from "@/lib/tmdb/tipos";

export function filtrosDeDuracao(
  duracao: Duracao,
): Pick<FiltrosDescoberta, "duracaoMin" | "duracaoMax"> {
  switch (duracao) {
    case "curta":
      return { duracaoMax: 90 };
    case "media":
      return { duracaoMin: 90, duracaoMax: 120 };
    case "longa":
      return { duracaoMin: 120 };
    case "indiferente":
      return {};
  }
}

/**
 * Quanto mais a pessoa assiste, menos óbvios os filmes: menos votos e nota mínimos
 * e páginas mais fundas do TMDB. Quem assiste pouco recebe os consagrados.
 */
export const PERFIS: Record<Frequencia, { votosMin: number; notaMin: number; paginaMax: number }> =
  {
    raramente: { votosMin: 2000, notaMin: 7, paginaMax: 2 },
    mensal: { votosMin: 1000, notaMin: 6.5, paginaMax: 3 },
    semanal: { votosMin: 300, notaMin: 6.5, paginaMax: 5 },
    diaria: { votosMin: 100, notaMin: 6, paginaMax: 10 },
  };

import Link from "next/link";
import type { ReactNode } from "react";

import { buttonVariants } from "@/components/ui/button";
import { SecaoRecomendacoes } from "@/features/dashboard/components/secao-recomendacoes";
import { gerarRecomendacoes } from "@/features/recomendacao/gerar";
import type { EntradaMotor } from "@/features/recomendacao/tipos";

type Props = {
  entrada: EntradaMotor;
  urlAtual: string;
  proximaRodada: string;
  /** Bloco que entra no meio das seções (o "Me surpreenda"). */
  meio?: ReactNode;
};

/** O bloco do meio entra depois desta quantidade de seções (ou no fim, se houver menos). */
const SECOES_ANTES_DO_MEIO = 2;

/** Parte lenta do dashboard: chama o motor e mostra as seções. Fica dentro de um Suspense. */
export async function SecoesRecomendadas({ entrada, urlAtual, proximaRodada, meio }: Props) {
  const secoes = await gerarRecomendacoes(entrada);

  if (secoes.length === 0) {
    return (
      <>
        <div className="text-muted-foreground flex flex-col items-start gap-3">
          <p>Não encontramos filmes com essas preferências.</p>
          <Link href={proximaRodada} className={buttonVariants({ variant: "outline" })}>
            Tentar outras recomendações
          </Link>
        </div>
        {meio}
      </>
    );
  }

  const secao = (item: (typeof secoes)[number]) => (
    <SecaoRecomendacoes key={item.id} secao={item} urlAtual={urlAtual} />
  );
  return (
    <>
      {secoes.slice(0, SECOES_ANTES_DO_MEIO).map(secao)}
      {meio}
      {secoes.slice(SECOES_ANTES_DO_MEIO).map(secao)}
    </>
  );
}
/** IDs de gênero de TV do TMDB (`/genre/tv/list`): outra lista que a dos filmes. */
export const TV = {
  acaoAventura: 10759,
  animacao: 16,
  comedia: 35,
  crime: 80,
  documentario: 99,
  drama: 18,
  familia: 10751,
  kids: 10762,
  misterio: 9648,
  news: 10763,
  reality: 10764,
  ficcaoFantasia: 10765,
  talk: 10767,
  guerraPolitica: 10768,
} as const;

/**
 * Gêneros de filme do perfil → gêneros de TV (tabela em SPEC/2026-11-19-series-descoberta.md).
 * Os que faltam aqui e não têm o mesmo ID em TV (Terror, Thriller, Romance, História, Música,
 * Cinema TV) não têm equivalente.
 */
const EM_TV: Record<number, number> = {
  28: TV.acaoAventura,
  12: TV.acaoAventura,
  878: TV.ficcaoFantasia,
  14: TV.ficcaoFantasia,
  10752: TV.guerraPolitica,
};
const MESMO_ID = new Set<number>([16, 35, 80, 99, 18, 10751, 37, 9648]);

/** Converte gêneros de filme (o perfil guarda esses) para gêneros de TV, sem repetir. */
export function generosEmTv(generosDeFilme: readonly number[]): number[] {
  const tv = generosDeFilme.flatMap((id) => {
    const equivalente = EM_TV[id] ?? (MESMO_ID.has(id) ? id : undefined);
    return equivalente === undefined ? [] : [equivalente];
  });
  return [...new Set(tv)];
}
import "server-only";

import { clienteTmdbPadrao, type ClienteTmdb, type Parametros } from "@/lib/tmdb/cliente";
import {
  anoDe,
  elencoDe,
  nuloSe404,
  ondeAssistirDe,
  paraGeneros,
  paraPagina,
  parametrosDescoberta,
  trailerDe,
  validar,
} from "@/lib/tmdb/comum";
import {
  detalhesSerieTmdb,
  generosTmdb,
  serieTmdb,
  type DetalhesSerieTmdb,
  type SerieTmdb,
} from "@/lib/tmdb/esquemas";
import type {
  ClassificacaoBR,
  FiltrosDescobertaSerie,
  OrdemDescoberta,
  Pagina,
  SerieDetalhes,
  SerieResumo,
} from "@/lib/tmdb/tipos";

const HORA = 3600;
const CACHE_LISTAS = 6 * HORA;
const CACHE_SERIE = 24 * HORA;

const ORDENS: Record<OrdemDescoberta, string> = {
  popularidade: "popularity.desc",
  nota: "vote_average.desc",
  lancamento: "first_air_date.desc",
};

/** Classificações do Brasil, da mais leve à mais restrita. */
export const CLASSIFICACOES_BR: readonly ClassificacaoBR[] = ["L", "10", "12", "14", "16", "18"];

function paraResumo(serie: SerieTmdb): SerieResumo {
  return {
    id: serie.id,
    titulo: serie.name,
    tituloOriginal: serie.original_name,
    sinopse: serie.overview,
    posterPath: serie.poster_path,
    backdropPath: serie.backdrop_path,
    generos: serie.genre_ids,
    ano: anoDe(serie.first_air_date),
    nota: serie.vote_average,
    votos: serie.vote_count,
    popularidade: serie.popularity,
  };
}

/** Média de `episode_run_time`; sem ela, a duração do último episódio exibido. */
function duracaoEpisodio(serie: DetalhesSerieTmdb): number | null {
  const duracoes = serie.episode_run_time.filter((minutos) => minutos > 0);
  if (duracoes.length === 0) return serie.last_episode_to_air?.runtime || null;
  return Math.round(duracoes.reduce((soma, minutos) => soma + minutos, 0) / duracoes.length);
}

function classificacaoDe(serie: DetalhesSerieTmdb): ClassificacaoBR | null {
  const doBrasil = serie.content_ratings.results.find((r) => r.iso_3166_1 === "BR")?.rating;
  return CLASSIFICACOES_BR.find((classificacao) => classificacao === doBrasil) ?? null;
}

function paraDetalhes(serie: DetalhesSerieTmdb): SerieDetalhes {
  return {
    ...paraResumo({ ...serie, genre_ids: [] }),
    generos: paraGeneros(serie.genres),
    duracaoEpisodioMin: duracaoEpisodio(serie),
    temporadas: serie.seasons
      .filter((temporada) => temporada.season_number > 0)
      .sort((a, b) => a.season_number - b.season_number)
      .map((temporada) => ({
        numero: temporada.season_number,
        nome: temporada.name,
        episodios: temporada.episode_count,
        ano: anoDe(temporada.air_date),
        posterPath: temporada.poster_path,
      })),
    slogan: serie.tagline,
    trailerYoutube: trailerDe(serie.videos.results),
    elenco: elencoDe(serie.credits),
    criacao: serie.created_by.map((pessoa) => pessoa.name),
    classificacao: classificacaoDe(serie),
    ondeAssistir: ondeAssistirDe(serie["watch/providers"]),
  };
}

/** Funções de séries sobre um cliente qualquer; os testes passam um cliente com `fetch` falso. */
export function criarApiSeries(cliente: ClienteTmdb) {
  return {
    async descobrirSeries(filtros: FiltrosDescobertaSerie = {}): Promise<Pagina<SerieResumo>> {
      const parametros: Parametros = {
        ...parametrosDescoberta(filtros, ORDENS),
        first_air_date_year: filtros.ano,
        "first_air_date.lte": filtros.lancadoAte,
      };
      const dados = await cliente.requisitar("/discover/tv", parametros, CACHE_LISTAS);
      return paraPagina(serieTmdb, dados, paraResumo);
    },

    obterSerie(id: number): Promise<SerieDetalhes | null> {
      return nuloSe404(async () => {
        const dados = await cliente.requisitar(
          `/tv/${id}`,
          { append_to_response: "videos,credits,watch/providers,content_ratings" },
          CACHE_SERIE,
        );
        return paraDetalhes(validar(detalhesSerieTmdb, dados));
      });
    },

    /** Gêneros de TV: outra lista que a dos filmes, com IDs próprios. */
    async generosSeries(): Promise<{ id: number; nome: string }[]> {
      const dados = await cliente.requisitar("/genre/tv/list", {}, CACHE_SERIE);
      return paraGeneros(validar(generosTmdb, dados).genres);
    },
  };
}

export type ApiSeries = ReturnType<typeof criarApiSeries>;

let padrao: ApiSeries | undefined;
const api = () => (padrao ??= criarApiSeries(clienteTmdbPadrao()));

export const descobrirSeries: ApiSeries["descobrirSeries"] = (...args) =>
  api().descobrirSeries(...args);
export const obterSerie: ApiSeries["obterSerie"] = (...args) => api().obterSerie(...args);
export const generosSeries: ApiSeries["generosSeries"] = () => api().generosSeries();
import type { Database } from "@/lib/supabase/database.types";

export type TipoMidia = Database["public"]["Enums"]["tipo_midia"];

export const TIPOS_MIDIA = ["filme", "serie"] as const satisfies TipoMidia[];

/**
 * Um título do TMDB. Só o ID não basta: filme e série têm sequências de ID independentes,
 * então o mesmo número pode ser os dois (pedido do cliente, 3.5).
 */
export type Midia = { tipo: TipoMidia; tmdbId: number };

/** Um número sozinho é filme, como na AP1: quem só lida com filmes continua passando o ID. */
export function lerMidia(alvo: number | Midia): Midia {
  return typeof alvo === "number" ? { tipo: "filme", tmdbId: alvo } : alvo;
}

/** Mensagem de quem grava quando o TMDB não conhece o título. */
export const NAO_ENCONTRADO: Record<TipoMidia, string> = {
  filme: "Filme não encontrado.",
  serie: "Série não encontrada.",
};

/** Página de detalhes de cada tipo. */
export function caminhoMidia({ tipo, tmdbId }: Midia): string {
  return `/${tipo}/${tmdbId}`;
}
